// @ts-strict-ignore
import { range } from "lodash-es";
import { DateHelper, NotificationHelper, getPrimaryDeliveryType, isNonEmptyArray } from ".";
import { ShopServiceCartContextType } from "../contexts";
import { Translation, corei18n } from "../labels/i18n";
import { Guest, GuestDTO, SelectablePass } from "../types/state/group-admission/group-admission-types";
import {
  CartRequestCartItem,
  DateSlotItem,
  DeliveryType,
  UpdateCartErrorCode,
  UpdateCartErrorCodeErrorResponse,
} from "@parksandresorts/webapiproxy-types";
import { WARNING_NOTIFICATION } from "@/core/components/primitives/notification-center/constants/notification-types";
import { TIME_PERSISTENT } from "@/core/components/primitives/notification-center/constants/time-types";
import { NormalizedProduct } from "../hooks/product-hooks";

export const mapAdmissionGuestToJetpassGuest = (guest: Guest, numberOfEntryTickets, numberOfJetpasses): any => {
  if (!guest.admissionProduct.id) {
    console.error("Missing product id on guest admission product.");
    return undefined;
  }
  const product = {
    glkId: guest.admissionProduct.id,
  };

  const jetpassGuest = {
    numberOfEntryTickets: numberOfEntryTickets,
    numberOfJetpasses: numberOfJetpasses,
    entryPasses: null,
    jetPasses: null,
    name: guest.name,
    product: product,
    productTimeLimit: guest.admissionProduct?.timeLimits ?? null,
    additionalInfo: {
      guestId: guest.id,
    },
  };

  return jetpassGuest;
};

export const mapJetpassGuestToGuestDTO = (jetPassGuest: any): GuestDTO => {
  const jetPasses = jetPassGuest.jetPasses ?? [];
  const guestDTO: GuestDTO = {
    id: jetPassGuest.additionalInfo.guestId,
    name: jetPassGuest.name,
    jetPasses: jetPasses.map(
      (jetPass: any) =>
        <SelectablePass>{
          attractionId: jetPass.attractionId,
          productId: jetPass.productId,
          attractionName: jetPass.attractionName,
          timeSlotId: jetPass.id,
          timeSlotFrom: jetPass.startDateTime,
          timeSlotTo: jetPass.endDateTime,
        },
    ),
  };

  return guestDTO;
};

export const updateCartErrorCodeMessage = (error?: UpdateCartErrorCodeErrorResponse) => {
  const errorList = error && isNonEmptyArray(error?.errors) && error.errors;

  if (!errorList)
    return {
      headline: corei18n.t("somethingWentWrong"),
      body: corei18n.t("somethingWentWrong"),
    };

  for (const error of errorList) {
    switch (error.errorCode) {
      case UpdateCartErrorCode.MAXIMUM_QUANTITY_EXCEEDED: {
        return {
          headline: corei18n.t("maximumQuantityExceededHeading"),
          body: corei18n.t("maximumQuantityExceeded"),
        };
      }
      case UpdateCartErrorCode.ITEM_CANNOT_BE_PURCHASED_WITH_GIFT_CARD: {
        return {
          headline: corei18n.t("cannotBePurchasedWithGiftCardHeading"),
          body: corei18n.t("cannotBePurchasedWithGiftCard"),
        };
      }
    }
  }
  return {
    headline: corei18n.t("somethingWentWrong"),
    body: corei18n.t("somethingWentWrong"),
  };
};

// This is a helper for both ActivityBooking and SeparateJetpassBooking, since their functionalities overlap _a lot_
export const addJetpassOrActivityCart = async (
  t: Translation,
  product: NormalizedProduct,
  numberOfTickets: number,
  selectedTimeSlot: SelectablePass | null,
  selectedDate: Date,
  calendarData: Array<Pick<DateSlotItem, "date" | "dateSlotId">>,
  setIsAddingToCart: (loading: boolean) => void,
  shopServiceContext: ShopServiceCartContextType,
) => {
  setIsAddingToCart(true);
  try {
    const dateData = calendarData.find((d) => DateHelper.isEqualYYYYMMDD(d.date, selectedDate));

    const deliveryType = getPrimaryDeliveryType(product, DeliveryType.DIGITAL);

    const cartItems = range(numberOfTickets).map(() => {
      return {
        productId: product.productId,
        quantity: 1,
        slot: {
          date: DateHelper.toStringYYYYMMDD(selectedDate),
          slotId: dateData?.dateSlotId,
        },
        deliveryType: deliveryType,
        subItems: [
          {
            productId: selectedTimeSlot.productId,
            quantity: 1,
            deliveryType: deliveryType,
            slot: {
              date: DateHelper.toStringYYYYMMDD(selectedDate),
              slotId: selectedTimeSlot.timeSlotId,
            },
          },
        ],
        visitorName: t("guest"),
      } satisfies CartRequestCartItem;
    });
    await shopServiceContext.addMultipleCartItems(cartItems);

    const addToCartHeadline = product.contentfulProduct?.addedToCartHeadline || t("addedToCartHeadline");
    const addToCartBody = product.contentfulProduct?.addedToCartBody || t("addedToCartBody");

    NotificationHelper.addCartNotification({
      headline: addToCartHeadline,
      body: addToCartBody,
    });
  } catch (err) {
    const error = err.error as UpdateCartErrorCodeErrorResponse;
    const { headline, body } = updateCartErrorCodeMessage(error);
    NotificationHelper.addNotification({
      notificationType: WARNING_NOTIFICATION,
      headline: headline,
      body: body,
      displayTime: TIME_PERSISTENT,
    });
  } finally {
    setIsAddingToCart(false);
  }
};
